\label{thm:BL62}
	Let $k\in \mathbb{N}_0$ and $r\in \mathbb{N}$ with $1\le r\le k+1$, let $p_r\ge 5$ be prime. For any $j\not\equiv 0\ \, \left( \mathrm{mod} \, p_{k+1} \right)$, if $p_{k+1}\not\equiv 7, 13 \ \, \left( \mathrm{mod} \, 24 \right)$ or $p_{k+1}\equiv 7, 13\ \, \left( \mathrm{mod} \, 24 \right)$ and $(\frac{3j}{p_{k+1}})=-1$, then with $P:=\prod_{r=1}^{k}p_r$, we have,
	\begin{align*}
	{\rm ou}^*\left(4P^2p^2_{k+1}n+2P^2p_{k+1} j+\frac{8P^2p^2_{k+1}+1}{3}\right)&\equiv0\ \, \left( \mathrm{mod} \, 4 \right)\qquad(j\ \text{odd}),\\
	{\rm ou}^*\left(4P^2p^2_{k+1}n+2P^2p_{k+1} j+\frac{2P^2p^2_{k+1}+1}{3}\right)&\equiv0\ \, \left( \mathrm{mod} \, 4 \right)\qquad(j\ \text{even}).
	\end{align*}

\label{thm1}
\begin{enumerate}[label=\textup{(\roman*)}]
	\item For $n\in \mathbb{N}$, ${\rm ou}(n)$ is odd iff $3n+1=4m^2$ for some $m\in\mathbb{Z}$.
	\item Let $n\in \mathbb{N}$ be odd. Then ${\rm ou}(n)\equiv0\ \, \left( \mathrm{mod} \, 4 \right)$ iff $3n+1$ is not a perfect square.
	\item Let $n\in \mathbb{N}$ be even. If $3n+1\ne m^2_1+3m^2_2$ for any $m_1,m_2\in \mathbb{Z}$, then ${\rm ou}(n)\equiv 0\ \, \left( \mathrm{mod} \, 4 \right)$. 
\end{enumerate}

\label{thm:watson}
We have,
	\begin{align}
	f(q^8)+2q\omega(q)+2q^3\omega\left(-q^4\right)&=\frac{\left(q^2;q^2\right)_\infty\left(q^4;q^4\right)_\infty^6}{(q)_\infty^2\left(q^8;q^8\right)_\infty^4},\label{W1}\\
	f(q)+4\psi(-q)&=\frac{(q)_\infty^3}{\left(q^2;q^2\right)_\infty^2},\label{W2}\\
	\nu(-q)&=q\omega\left(q^2\right)+\frac{\left(q^4;q^4\right)_\infty^3}{\left(q^2;q^2\right)_\infty^2}.\label{thm:fine}
	\end{align}

\label{L:CC}
	Let $n\in\mathbb N_0$. We have,
		 \[c_1(n)\equiv2\ \, \left( \mathrm{mod} \, 4 \right)\Leftrightarrow 6n+1\in S_2^{[1]}.\]

By \Cref{lem1}, we have
\begin{align*}
\sum_{n\ge 0}{\rm ou}(n)q^n&\equiv \sum_{n\ge 0}q^{3n^2+2n}\left(1+q^{2n+1}\right)+\frac{\left(q^2;q^2\right)^2_{\infty}}{\left(q\right)^2_{\infty}}\sum_{n\ge 0} q^{n(n+1)}\\
&\equiv \sum_{n\in \mathbb{Z}}q^{3n^2+2n}+\left(q^8;q^8\right)_{\infty}\equiv \sum_{n\in \mathbb{Z}}q^{3n^2+2n}+\sum_{n\in \mathbb{Z}}q^{12n^2-4n}\ \, \left( \mathrm{mod} \, 2 \right).
\end{align*}
using \Cref{lem2}, $(q)^2_{\infty}\equiv (q^2;q^2)_{\infty}\ \, \left( \mathrm{mod} \, 2 \right)$, and $(q^4;q^4)^2_{\infty}\equiv (q^8;q^8)_{\infty}\ \, \left( \mathrm{mod} \, 2 \right)$ in the second step, \Cref{lem2} in the final step. Letting $q\mapsto q^3$ and multiplying both sides by $q$, it follows that,
\begin{align*}
\sum_{n\ge 0}{\rm ou}(n)q^{3n+1}&\equiv \sum_{n\in \mathbb{Z}} q^{(3n+1)^2}+\sum_{n\in \mathbb{Z}} q^{(6n-1)^2}\equiv \sum_{\substack{n\ge 1\\n\ \text{even}\\3\nmid n}}q^{n^2}\ \, \left( \mathrm{mod} \, 2 \right).
\end{align*} 
This concludes the proof of \Cref{thm1} (i).

Next, by \Cref{lem1}, we have
\begin{align}\label{eqn2}
&\sum_{n\ge 0}{\rm ou}(n)q^n=\sum_{n\ge 0}(-1)^{n+1}q^{3n^2+2n}\left(1+q^{2n+1}\right)+\frac{\left(q^2;q^2\right)^2_{\infty}}{\left(q\right)^2_{\infty}}\sum_{n\ge 0} (-1)^nq^{n(n+1)}\nonumber\\
&\hspace{0.5 cm}\equiv \sum_{n\ge 0}(-1)^{n+1}q^{3n^2+2n}\left(1+q^{2n+1}\right)+(q)^2_{\infty}\sum_{n\ge 0} (-1)^nq^{n(n+1)}\nonumber\\
&\hspace{0.5 cm}\equiv \sum_{n\ge 0}(-1)^{n+1}q^{3n^2+2n}\left(1+q^{2n+1}\right)+\frac{(q)^2_{\infty}}{\left(q^2;q^2\right)_{\infty}}\sum_{\substack{n\ge 0\\m\in \mathbb{Z}}} (-1)^{m+n} q^{n(n+1)+m\left(3m-1\right)}\ \, \left( \mathrm{mod} \, 4 \right),
\end{align}
using $(q)^4_{\infty}\equiv (q^2;q^2)^2_{\infty}\ \, \left( \mathrm{mod} \, 4 \right)$ in the second step and \Cref{lem2} in the final step. For $N\in \mathbb{N}_0$ and\footnote{Here and throughout, $R[[q]]$ denotes the ring of formal power series in $q$ over a commutative ring $R$.} $A(q):=\sum_{n\ge 0}a(n)q^n\in \mathbb{Z}[[q]]$, $[q^N](A(q)):=a(N)$. We set 
\begin{equation}\label{eqn2a}
S_1(q):=\sum_{n\ge 0}(-1)^{n+1}q^{3n^2+2n}\left(1+q^{2n+1}\right)=:\sum_{n\ge 0}s_1(n)q^n
\end{equation}
and note that $s_1(n)\in \{-1,0,1\}$ for $n\in \mathbb{N}_0$. Moreover, since 
\begin{equation}\label{eqn2b}
3\left(3n^2+2n\right)+1=(3n+1)^2,\quad 3\left(3n^2+4n+1\right)+1=\left(3n+2\right)^2,
\end{equation}
we have, for $N$ odd and $3N+1\neq m^2$ (for all $m\in 2\mathbb{Z}$), 
\[
s_1(N)=0.
\]
Thus, with
\begin{equation}\label{eqn2c}
S_2(q):=\frac{(q)^2_{\infty}}{\left(q^2;q^2\right)_{\infty}},\quad S_3(q):=\sum_{\substack{n\ge 0\\m\in \mathbb{Z}}} (-1)^{m+n} q^{n(n+1)+m\left(3m-1\right)}=:\sum_{k\ge 0}s_3(k)q^k,
\end{equation} 
and using \Cref{lem2}, \eqref{eqn2} becomes
\begin{align*}
{\rm ou}\left(N\right)&\equiv \left[q^N\right]\left(S_2(q)S_3(q)\right)\equiv \sum_{m\in \mathbb{Z}}(-1)^m s_3\left(N-m^2\right)\equiv 2\sum_{\substack{m\ge 1\\2\nmid m}} s_3\left(N-m^2\right)\ \, \left( \mathrm{mod} \, 4 \right),
\end{align*}
using $s_3(n)=0$ for $n$ odd in the final step. Thus, to conclude the proof, it suffices to show that
\begin{equation}\label{eqn4}
\left|X_1(N)\right|\equiv 0\ \, \left( \mathrm{mod} \, 2 \right),\ \ \text{where}\ \ X_1(N):=\left\{m\in \mathbb{N}: 2\nmid m, s_3\left(N-m^2\right)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\right\}.
\end{equation}

Next, we show that
\begin{equation}\label{eqn5}
s_3(k)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\Leftrightarrow 3k+1=\ell^2\ \text{with}\ \gcd\left(\ell,6\right)=1.
\end{equation}
 Now, by definition of $s_3(k)$, we have
\begin{align}\label{eqn5a}
s_3(k)=\sum_{(n,m)\in X_2(k)}(-1)^{n+m}\ \text{with}\ X_2(k):=\left\{(n,m)\in \mathbb{N}_0\times \mathbb{Z}: n(n+1)+m(3m-1)=k\right\}.
\end{align}
Define $X_3(k):=\{(n,m)\in \mathbb{N}^2: 2\nmid n,\ \gcd(m,6)=1,\ m^2+3n^2=k\}$ and  $f_1:X_2(k)\rightarrow X_3(12k+4)$ with $f_1(n,m):=(2n+1,|6m-1|)$. Clearly, $f_1$ is well defined and bijective. Thus $|X_2(k)|=|X_3(12k+4)|$ and so
\begin{equation}\label{eqn6}
s_3(k)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\Leftrightarrow \left|X_3\left(12k+4\right)\right|\equiv 1\ \, \left( \mathrm{mod} \, 2 \right).
\end{equation}
By \Cref{lem4}, we have, for $3\nmid k$,
\begin{equation}\label{eqn7}
\left|X_3(k)\right|=\begin{cases}
D_3\left(\frac k4\right) &\text{if}\ k\equiv 4\ \, \left( \mathrm{mod} \, 8 \right),\\
0 &\text{otherwise}.
\end{cases}
\end{equation}
Since, by definition, $D_3$ is multiplicative, for $k\in \mathbb{N}$ with $3\nmid k$, 
\begin{equation}\label{eqn7a}
D_3(k)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\Leftrightarrow k=\ell^2.
\end{equation}
Thus, combining \eqref{eqn6} and \eqref{eqn7}, it follows that
\[
s_3(k)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\Leftrightarrow 3k+1=\ell^2\ \text{with}\ \gcd\left(\ell,6\right)=1.
\]
Since for given $N$ and $m$, such $\ell$ is unique, thus, from \eqref{eqn4}, we get
\[
X_1(N)=\left\{m\in \mathbb{N}: 2\nmid m, \ell^2+3m^2=3N+1\ \text{with}\ \gcd\left(\ell,6\right)=1\right\}.
\]
Define $f_2:X_1(N)\rightarrow X_3(3N+1)$ by $f_2(m):=(m,\sqrt{3N+1-3m^2})$ and we observe that $f_2$ is a bijection. Thus,
\[
\left|X_1(N)\right|=\left|X_3\left(3N+1\right)\right|\equiv 0\ \, \left( \mathrm{mod} \, 2 \right),
\]
using \eqref{eqn7}, \eqref{eqn7a}, and $3N+1\neq m^2$ for any $m$ even. 

Finally, assume that $3n+1$ is a square. Since $n$ is odd, $3n+1=4m^2$ for some $m\in \mathbb{Z}$ and by (i), ${\rm ou}(n)\not\equiv 0\ \, \left( \mathrm{mod} \, 4 \right)$. This concludes the proof of \eqref{eqn4}.


Finally, we now prove (iii). By \eqref{eqn2a} and \eqref{eqn2b}, for $N\in \mathbb{N}$ even and $3N+1\neq m^2$ (since, by hypothesis $3N+1\neq m^2_1+3m^2_2$ for any $m_1,m_2\in \mathbb{Z}$), $s_1(N)=0$. Thus, with \eqref{eqn2c}, for $N$ even, \eqref{eqn2} becomes
\begin{align}\label{eqn8}
{\rm ou}(N)&\equiv \sum_{m\in \mathbb{Z}}(-1)^m s_3\left(N-m^2\right)=s_3(N)+2\sum_{m\ge 1}s_3\left(N-4m^2\right)\ \, \left( \mathrm{mod} \, 4 \right),
\end{align}
using $s_3(n)=0$ for $n$ odd. Moreover, by \eqref{eqn5}, we obtain
\[
s_3\left(N-4m^2\right)\equiv 1\ \, \left( \mathrm{mod} \, 2 \right)\Leftrightarrow 3N+1=\ell^2+12m^2
\]
and this contradicts the assumption that $3N+1=m^2_1+3m^2_2$ for any $m_1,m_2\in \mathbb{Z}$. Consequently, \eqref{eqn8} yields
\begin{equation}\label{eqn9}
{\rm ou}(N)\equiv s_3(N)\ \, \left( \mathrm{mod} \, 4 \right).
\end{equation} 
Since $N$ even and $3N+1\neq m^2_1+3m^2_2$ for any $m_1,m_2\in \mathbb{N}$, $X_2(N)=\emptyset$. Therefore, by \eqref{eqn5a}, $s_3(N)=0$ and so, from \eqref{eqn9}, we conclude the proof.\qedhere

\label{assistlem0}
We have, for $n\in \mathbb{N}$ and modulo $4$, 
\begin{align*}
c_\omega(4n-3)&\equiv c_1(n-1),\quad c_\omega\left(8n-6\right)\equiv 2c_2(n-1),\quad c_\omega\left(8n-8\right)\equiv 2c_{\psi}(n-1),\\
 c_\omega(4n-1)&\equiv(-1)^n c_\omega(n).
\end{align*}

By \Cref{lem2}, we have
\[
(q)_\infty\left(q^4;q^4\right)_\infty=\sum_{r,s\in\mathbb{Z}}(-1)^{r+s}q^{\frac{r(3r-1)}2+2s(3s-1)}.
\]
Thus, by definition of $c_2(n)$ (see above \Cref{assistlem0}), 
\begin{equation}\label{eqn11}
c_2(n)\equiv\left|X_4(n)\right|\ \, \left( \mathrm{mod} \, 2 \right)\ \ \text{with}\ \ X_4(n):=\left\{(r,s)\in\mathbb{Z}^2: \frac{r(3r-1)}2+2s(3s-1)=n\right\}.
\end{equation}
Note that
\[
X_4(n)=\left\{(r,s)\in\mathbb{Z}^2:r\equiv s\equiv 5\ \, \left( \mathrm{mod} \, 6 \right), r^2+4s^2=24n+5\right\}.
\]
Setting $X_5(n):=\{(r,s)\in\mathbb{Z}^2: r^2+4s^2=24n+5\}$, define a map $f_3:X_5(n)\rightarrow X_4(n)$ by $f_3(r,s):=(-(\frac r3)r,-(\frac s3)s)$. We observe that $f_3\mid_{X_4(n)}={\rm Id}$ and $f_3$ is surjective. Moreover, for $(r,s)\in X_4(n)$, $f^{-1}_3((r,s))\in \{(\pm r,\pm s)\}$, i.e., every fibre of $f_3$ has exactly $4$ distinct elements and thus, by \eqref{eqn11},
\begin{equation}\label{eqn12}
c_2(n)\equiv \left|X_4(n)\right|=\frac 14\left|X_5(n)\right|\ \, \left( \mathrm{mod} \, 2 \right).
\end{equation}

Next, define
\begin{align*}
X_6(n)&:=\left\{(r,s)\in\mathbb{Z}^2: r^2+s^2=24n+5\right\},\quad X^{[1]}_6(n):=\left\{(r,s)\in X_6: s\ \text{even}\right\},\\
  X^{[2]}_6(n)&:=\left\{(r,s)\in X_6: r\ \text{even}\right\}.
\end{align*}
Clearly, $|X_6(n)|=r_2(24n+5)=|X^{[1]}_6(n)|+|X^{[2]}_6(n)|$ because $X^{[1]}_6(n)\cap X^{[2]}_6(n)=\emptyset$. Define $f_4:X^{[2]}_6(n)\mapsto X^{[1]}_6(n)$ by $f_4((r,s)):=((s,r))$ and clearly, $f_4$ is a bijection. Therefore, 
\[
\left|X_6(n)\right|=r_2(24n+5)=2\left|X^{[1]}_6(n)\right|.
\]
Moreover, define $f_5:X_5(n)\rightarrow X^{[1]}_6(n)$ by $f_5((r,s)):=(r,2s)$ and noting the fact that $f^{-1}_5((r,s))=(r,\frac s2)$ is the inverse map, $f_5$ is a bijection. Therefore, by \eqref{eqn12} and \Cref{lem5}, we have
\begin{equation}\label{eqn13}
c_2(n)\equiv \frac{r_2\left(24n+5\right)}{8}=\frac{1}{2}\sum_{d\mid 24n+5}\chi_{-4}(d)\ \, \left( \mathrm{mod} \, 2 \right).
\end{equation}
Write\footnote{Here and throughout, for primes $\ell$, $\nu_{\ell}(n)$ denotes the $\ell$-adic valuation of $n$.} $24n+5=\prod_{\ell\mid 24n+5}\ell^{\nu_{\ell}(24n+5)}$ and using the fact that $\chi_{-4}$ is completely multiplicative, it is not hard to see that,
\begin{equation}\label{eqn14}
\frac{1}{2}\sum_{d\mid 24n+5}\chi_{-4}(d)=\frac 12\prod_{\ell\mid 24n+5}\sum_{j=0}^{\nu_\ell\left(24n+5\right)}\chi_{-4}(\ell)^j
\end{equation}
and 
\begin{equation}\label{eqn15}
\sum_{j=0}^{\nu_{\ell}\left(24n+5\right)}\chi_{-4}(\ell)^j=\begin{cases}\nu_\ell\left(24n+5\right)+1&\ell\equiv1\ \, \left( \mathrm{mod} \, 4 \right),\\ 1&\ell\equiv3\ \, \left( \mathrm{mod} \, 4 \right)\ \text{with}\ \nu_\ell\left(24n+5\right)\ \text{even},\\
0&\ell\equiv3\ \, \left( \mathrm{mod} \, 4 \right)\ \text{with}\ \nu_\ell\left(24n+5\right)\ \text{odd}.\end{cases}
\end{equation}


Now, assume that $24n+5\in S^{[1]}_2$. By definition of $ S^{[1]}_2$, $p\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)$, and consequently, by \eqref{eqn15}, we have
\[
\sum_{j=0}^{\nu_{p}\left(24n+5\right)}\chi_{-4}(p)^j\equiv 2\ \, \left( \mathrm{mod} \, 4 \right),\qquad \sum_{\substack{j=0\\\ell\neq p}}^{\nu_{\ell}\left(24n+5\right)}\chi_{-4}(\ell)^j\equiv 1\ \, \left( \mathrm{mod} \, 2 \right).
\]
Plugging this into \eqref{eqn13} and then by \eqref{eqn13}, we conclude that $c_2(n)$ is odd.

Finally, we assume that $c_2(n)$ is odd. By \eqref{eqn13} and \eqref{eqn14}, this is equivalent to 
\begin{align}\label{eqn16}
&\sum_{d\mid 24n+5}\chi_{-4}(d)\equiv 2\ \, \left( \mathrm{mod} \, 4 \right)\Leftrightarrow \!\!\!\prod_{\ell\mid 24n+5}\sum_{j=0}^{\nu_\ell\left(24n+5\right)}\chi_{-4}(\ell)^j\equiv 2\ \, \left( \mathrm{mod} \, 4 \right)\nonumber\\
&\hspace{4 cm}\Leftrightarrow \!\!\!\prod_{\substack{\ell\mid 24n+5\\\ell\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)}}\!\!\!\sum_{j=0}^{\nu_\ell\left(24n+5\right)}\chi_{-4}(\ell)^j\!\!\prod_{\substack{\ell\mid 24n+5\\\ell\equiv 3\ \, \left( \mathrm{mod} \, 4 \right)}}\!\!\!\sum_{j=0}^{\nu_\ell\left(24n+5\right)}\chi_{-4}(\ell)^j\equiv 2\ \, \left( \mathrm{mod} \, 4 \right).
\end{align}
Thus, by \eqref{eqn15}, for $\ell\equiv 3\ \, \left( \mathrm{mod} \, 4 \right)$ and $\ell\mid 24n+5$, 
\begin{equation}\label{eqn17}
\nu_{\ell}\left(24n+5\right)\equiv 0\ \, \left( \mathrm{mod} \, 2 \right).
\end{equation}
Therefore, \eqref{eqn16} reduces to
\begin{align*}
&\prod_{\substack{\ell\mid 24n+5\\\ell\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)}}\!\!\!\sum_{j=0}^{\nu_\ell\left(24n+5\right)}\chi_{-4}(\ell)^j\equiv 2 \ \, \left( \mathrm{mod} \, 4 \right)\Leftrightarrow \prod_{\substack{\ell\mid 24n+5\\\ell\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)}}\left(\nu_{\ell}\left(24n+5\right)+1\right)\equiv 2\ \, \left( \mathrm{mod} \, 4 \right)\\
&\Leftrightarrow \nu_2\left(\prod_{\substack{\ell\mid 24n+5\\\ell\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)}}\left(\nu_{\ell}\left(24n+5\right)+1\right)\right)=1\Leftrightarrow \sum_{\substack{\ell\mid 24n+5\\\ell\equiv 1\ \, \left( \mathrm{mod} \, 4 \right)}}\nu_2\left(\nu_{\ell}\left(24n+5\right)+1\right)=1.
\end{align*}
Since $\nu_2(n)\ge 0$ for $n\in \mathbb{N}$, this directly implies that there exists a unique prime, say $p\equiv1\ \, \left( \mathrm{mod} \, 4 \right)$ with $p\mid 24n+5$ and 
\[
\nu_{p}\left(24n+5\right)+1\equiv 2\ \, \left( \mathrm{mod} \, 4 \right)\Leftrightarrow \nu_p\left(24n+5\right)\equiv 1 \ \, \left( \mathrm{mod} \, 4 \right).
\]
Combining this and \eqref{eqn17}, $24n+5\in S^{[1]}_2$. This concludes the proof.\qedhere

\label{con1}
	Let $\alpha\in \mathbb{N}_{\ge 3}$, $A_{\alpha}, B_{\alpha}\in \mathbb{N}$.	Determine (if exists) arithmetic progression $A_{\alpha}n+B_{\alpha}$ such that, for  all $n\in \mathbb{N}_0$, 
	\[{\rm ou}\left(A_{\alpha}n+B_{\alpha}\right)\equiv 0\ \, \left( \mathrm{mod} \, 2^{\alpha} \right).\]

\label{conj2}
Let $\alpha\in \mathbb{N}_{\ge 3}$. Then there does not exist $C_{\alpha}, D_{\alpha}\in \mathbb{N}$, such that for all $n\in \mathbb{N}_0$, 
\[{\rm ou}^*\left(C_{\alpha}n+D_{\alpha}\right)\equiv 0\ \, \left( \mathrm{mod} \, 2^{\alpha} \right).\]
